def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the repeating color cycle from the unmasked interior.
    cells = [(r + c, grid[r][c])
             for r in range(3, h) for c in range(3, w)
             if grid[r][c] != 0]

    best_period = 5
    best_mapping = {}
    best_score = -1
    for period in range(2, 10):
        counts = [{} for _ in range(period)]
        for phase, color in cells:
            bucket = counts[phase % period]
            bucket[color] = bucket.get(color, 0) + 1
        mapping = {
            i: max(bucket, key=bucket.get)
            for i, bucket in enumerate(counts) if bucket
        }
        score = sum(max(bucket.values()) for bucket in counts)
        if score > best_score:
            best_period, best_mapping, best_score = period, mapping, score

    outer = grid[0][0]
    frame_values = []
    for c in range(2, w):
        if grid[2][c] != 0:
            frame_values.append(grid[2][c])
    for r in range(2, h):
        if grid[r][2] != 0:
            frame_values.append(grid[r][2])
    frame = max(set(frame_values), key=frame_values.count) if frame_values else 4

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = outer
            elif r == 2 or c == 2:
                out[r][c] = frame
            else:
                out[r][c] = best_mapping[(r + c) % best_period]
    return out
